package com.mengzhihua.crm.sales.controller;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.Account;import com.mengzhihua.crm.sales.service.AccountService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/accounts") public class AccountController {private final AccountService s;public AccountController(AccountService x){s=x;}@GetMapping public Result<PageResult<Account>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String keyword){return Result.ok(s.list(page,size,keyword));}@GetMapping("/{id}")public Result<Account> get(@PathVariable Long id){return Result.ok(s.get(id));}@GetMapping("/{id}/overview")public Result<?> overview(@PathVariable Long id){return Result.ok(s.overview(id));}@PostMapping public Result<Account> add(@RequestBody Account x){return Result.ok(s.save(x));}@PutMapping("/{id}")public Result<Account> edit(@PathVariable Long id,@RequestBody Account x){x.setId(id);return Result.ok(s.save(x));}@DeleteMapping("/{id}")public Result<Void> del(@PathVariable Long id){s.delete(id);return Result.ok();}}
